(6938864, 1044976, 49109, '<td valign="top">Congrats on the Hm, Bear, very dramatic and thus great for the challenge.</td>', 'Congrats on the Hm, Bear, very dramatic and thus great for the challenge.', '2012-12-21 05:05:31.000000', NULL, 0),
(6938867, 1045038, 114969, '<td valign="top">Creative, well composed, well lit, flawless composite, great story telling: congratulations Oliver on this very convincing and impressive entry. I''m glad it finished well, much deserved!</td>', 'Creative, well composed, well lit, flawless composite, great story telling: congratulations Oliver on this very convincing and impressive entry. I''m glad it finished well, much deserved!', '2012-12-21 05:10:55.000000', NULL, 0),
(6938869, 1045142, 114969, '<td valign="top">I agree with you Alessandro, definitely one of your very best ''expert editing'' entry. The concept is very interesting, and there are many ways to look at it, which lets the viewer imagine himself in that situation. Congratulations on the HM.</td>', 'I agree with you Alessandro, definitely one of your very best ''expert editing'' entry. The concept is very interesting, and there are many ways to look at it, which lets the viewer imagine himself in that situation. Congratulations on the HM.', '2012-12-21 05:18:35.000000', NULL, 0),
(6938875, 1045059, 109387, '<td valign="top">It''s a very nice image Giles. Probably with a slightly different composition (not tilted and with the road more visible) you could get an even better result.</td>', 'It''s a very nice image Giles. Probably with a slightly different composition (not tilted and with the road more visible) you could get an even better result.', '2012-12-21 05:37:42.000000', NULL, 0),
