(6938902, 1045142, 109387, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Tommy_Mac:</b></div><hr/><i> Congrats on the HM brother! And I can''t beleive you are up!!!! :-) </i></td></tr></table> <br/> <br/>I have an uninterruptible power supply. It seems I don''t need sleeping (that''s Christophe''s secret) :)</td>', 'Originally posted by Tommy_Mac: Congrats on the HM brother! And I can''t beleive you are up!!!! :-)   I have an uninterruptible power supply. It seems I don''t need sleeping (that''s Christophe''s secret) :)', '2012-12-21 07:25:50.000000', NULL, 0),
(6938909, 1045142, 54446, '<td valign="top">Strikingly beautiful image.  It''s a fine work of art.  Pleasant to view.  Big congrats on a well earned HM.  Should have ribboned.</td>', 'Strikingly beautiful image.  It''s a fine work of art.  Pleasant to view.  Big congrats on a well earned HM.  Should have ribboned.', '2012-12-21 07:48:58.000000', NULL, 0),
(6938910, 1045080, 54446, '<td valign="top">Magnificent photo.  And, it''s a real photo.  Thanks so much for this excellent photography.  Love the idea.  It''s a joy to view.  Congrats on your ribbon.</td>', 'Magnificent photo.  And, it''s a real photo.  Thanks so much for this excellent photography.  Love the idea.  It''s a joy to view.  Congrats on your ribbon.', '2012-12-21 07:50:38.000000', NULL, 0),
